/**
 * Node-RED TypeScript Type Definitions
 * Enhanced type definitions for Node-RED with TypeScript support
 */

declare namespace NodeRED {
    interface Node {
        id: string;
        name: string;
        type: string;
        z: string;
        _flow: Flow;
        _path: string;
        wires: string[][];
        
        // Methods
        send(msg: NodeMessage | NodeMessage[]): void;
        error(error: string | Error, msg?: NodeMessage): void;
        warn(warning: string): void;
        log(message: string): void;
        debug(message: string): void;
        trace(message: string): void;
        status(options: NodeStatus): void;
        
        // Context
        context(): NodeContext;
        
        // Events
        on(event: 'input', callback: (msg: NodeMessage, send: SendFunction, done: DoneFunction) => void): void;
        on(event: 'close', callback: (removed: boolean, done: () => void) => void): void;
        on(event: string, callback: Function): void;
        
        // Metrics
        metric(eventname: string, msg: NodeMessage, metricValue: number): void;
        
        // Utilities
        ready(): Promise<void>;
    }

    interface NodeMessage {
        payload: any;
        topic?: string;
        _msgid?: string;
        req?: any;
        res?: any;
        cookies?: { [key: string]: string };
        [key: string]: any;
    }

    interface NodeStatus {
        fill?: 'red' | 'green' | 'yellow' | 'blue' | 'grey';
        shape?: 'ring' | 'dot';
        text?: string;
    }

    interface NodeContext {
        set(key: string, value: any, store?: string, callback?: (err: Error) => void): void;
        get(key: string, store?: string, callback?: (err: Error, value: any) => void): any;
        keys(store?: string, callback?: (err: Error, keys: string[]) => void): string[];
        
        flow: FlowContext;
        global: GlobalContext;
    }

    interface FlowContext {
        set(key: string, value: any, store?: string, callback?: (err: Error) => void): void;
        get(key: string, store?: string, callback?: (err: Error, value: any) => void): any;
        keys(store?: string, callback?: (err: Error, keys: string[]) => void): string[];
    }

    interface GlobalContext {
        set(key: string, value: any, store?: string, callback?: (err: Error) => void): void;
        get(key: string, store?: string, callback?: (err: Error, value: any) => void): any;
        keys(store?: string, callback?: (err: Error, keys: string[]) => void): string[];
    }

    interface Flow {
        id: string;
        getSetting(key: string): any;
    }

    type SendFunction = (msg: NodeMessage | NodeMessage[]) => void;
    type DoneFunction = (err?: Error) => void;

    // Enhanced Function Node Configuration
    interface FunctionNodeConfig {
        id: string;
        type: "function";
        name: string;
        func: string;
        language?: 'javascript' | 'typescript';
        compilerOptions?: TypeScriptCompilerOptions;
        outputs: number;
        timeout?: number;
        noerr?: boolean;
    }

    interface TypeScriptCompilerOptions {
        target?: 'ES5' | 'ES6' | 'ES2015' | 'ES2016' | 'ES2017' | 'ES2018' | 'ES2019' | 'ES2020' | 'ES2021' | 'ES2022' | 'ESNext';
        module?: 'CommonJS' | 'AMD' | 'System' | 'UMD' | 'ES6' | 'ES2015' | 'ES2020' | 'ESNext' | 'None';
        strict?: boolean;
        esModuleInterop?: boolean;
        skipLibCheck?: boolean;
        allowJs?: boolean;
        checkJs?: boolean;
    }

    // Schema Node Configuration
    interface SchemaNodeConfig {
        id: string;
        type: "schema";
        name: string;
        schemaName: string;
        schemaCode: string;
        export: boolean;
    }

    // RED API
    interface RED {
        nodes: {
            createNode(node: any, config: any): void;
            registerType(type: string, constructor: any, opts?: any): void;
            getNode(id: string): Node | null;
        };
        
        util: {
            cloneMessage(msg: NodeMessage): NodeMessage;
            generateId(): string;
            getMessageProperty(msg: NodeMessage, prop: string): any;
            setMessageProperty(msg: NodeMessage, prop: string, value: any, createMissing?: boolean): boolean;
            evaluateNodeProperty(value: any, type: string, node: Node, msg: NodeMessage, callback?: Function): any;
        };
        
        log: {
            info(msg: string): void;
            warn(msg: string): void;
            error(msg: string): void;
            debug(msg: string): void;
            trace(msg: string): void;
            metric(): any;
            addHandler(handler: any): void;
            removeHandler(handler: any): void;
        };
        
        library: {
            register(type: string): void;
            create(options: LibraryCreateOptions): void;
        };
        
        editor: {
            createEditor(options: EditorOptions): any;
        };
        
        events: {
            on(event: string, callback: Function): void;
            emit(event: string, ...args: any[]): void;
            removeListener(event: string, callback: Function): void;
        };
        
        settings: {
            get(key: string): any;
            set(key: string, value: any): void;
        };
        
        httpAdmin: any;
        httpNode: any;
        server: any;
        
        // Internationalization
        _(key: string, options?: any): string;
    }

    interface LibraryCreateOptions {
        url: string;
        type: string;
        editor: any;
        mode?: string;
        fields?: string[];
    }

    interface EditorOptions {
        id: string;
        mode: string;
        value: string;
        globals?: { [key: string]: boolean };
    }

    // Environment utilities
    interface EnvVarOptions {
        node?: Node;
        flow?: Flow;
        global?: any;
    }
}

// Global declarations for Node-RED function context
declare var RED: NodeRED.RED;
declare var msg: NodeRED.NodeMessage;
declare var node: NodeRED.Node;
declare var context: NodeRED.NodeContext;
declare var flow: NodeRED.FlowContext;
declare var global: NodeRED.GlobalContext;
declare var env: {
    get(name: string): string | undefined;
};

// Console and timers (available in function nodes)
declare var console: Console;
declare var Buffer: BufferConstructor;
declare var setTimeout: typeof global.setTimeout;
declare var clearTimeout: typeof global.clearTimeout;
declare var setInterval: typeof global.setInterval;
declare var clearInterval: typeof global.clearInterval;

// Zod integration
declare var z: typeof import('zod');
declare var zod: typeof import('zod');

// Module declarations for Node-RED scripts
declare module '@node-red/scripts/*' {
    const content: any;
    export = content;
}

// Export the main module function type
declare type NodeRedModule = (RED: NodeRED.RED) => void;

export = NodeRED;
export as namespace NodeRED;